    description: { de: "Das älteste bestehende Gebäude in Dubai diente einst als Verteidigungsanlage, Palast und Gefängnis.", hu: "Dubaj legrégebbi fennmaradt épülete egykor védelmi célokat szolgált, de volt palota és börtön is.", ro: "Cea mai veche clădire existentă din Dubai a servit cândva ca structură de apărare, palat și închisoare.", en: "The oldest existing building in Dubai once served as a defense structure, palace, and prison." , es: "El edificio más antiguo de Dubái sirvió en su día como instalación defensiva, palacio y prisión.", pt: "O edifício mais antigo do Dubai serviu outrora como instalação defensiva, palácio e prisão.", fr: "Le plus ancien bâtiment existant à Dubaï a servi autrefois d'installation de défense, de palais et de prison."},
    facts: {
      de: ["Erbaut im späten 18. Jahrhundert.", "Beherbergt heute das Dubai Museum."],
      hu: ["A 18. század végén épült.", "Ma a Dubaji Múzeumnak ad otthont."],
      ro: ["Construit la sfârșitul secolului al XVIII-lea.", "Găzduiește astăzi Muzeul din Dubai."],
      en: ["Built in the late 18th century.", "Now houses the Dubai Museum."],
      es: ["Construido a finales del siglo XVIII.", "Hoy alberga el Museo de Dubái."],
      pt: ["Construído no final do século XVIII.", "Hoje alberga o Museu do Dubai."],
      fr: ["Construit à la fin du XVIIIe siècle.", "Abrite aujourd'hui le musée de Dubaï."],
    }, image: "/poi-images/al-fahidi-fort-history-v2.webp",
    descriptionAdvanced: {
      de: "Das Al Fahidi Fort wurde im Jahr 1787 erbaut und ist das älteste noch bestehende Gebäude in Dubai. Ursprünglich diente es als Verteidigungsanlage zum Schutz der Stadt vor Invasionen vom Meer und vom Land aus und war zudem der Sitz der Herrscherfamilie. Die quadratische Festung verfügt über drei markante Türme und Mauern aus Korallengestein und Muschelkalk, die mit Kalkmörtel verbunden sind. Im Laufe seiner Geschichte fungierte das Fort als Garnison, Waffenlager und Gefängnis, bevor es 1971 in das Dubai Museum umgewandelt wurde. Heute bietet das Museum in den unterirdischen Galerien faszinierende Einblicke in die Geschichte Dubais, von den archäologischen Funden bis hin zum täglichen Leben vor der Entdeckung des Öls. Die Ausstellungen zeigen traditionelle Boote, Waffen und Rekonstruktionen lokaler Marktplätze. Das Al Fahidi Fort bleibt ein zentrales kulturelles Symbol, das das historische Erbe inmitten der modernen Metropole bewahrt.",
      hu: "Az Al Fahidi erőd 1787-ben épült, és ez Dubai legrégebbi fennmaradt épülete. Eredetileg védelmi célokat szolgált a tengeri és szárazföldi támadások ellen, emellett az uralkodócsalád rezidenciája is volt. A négyszögletes erőd három jellegzetes toronnyal rendelkezik, falai pedig korallkőből és kagylómészből készültek, amelyeket mészhabarccsal rögzítettek. Története során az erőd laktanyaként, fegyverraktárként és börtönként is funkcionált, mielőtt 1971-ben megnyitották benne a Dubai Múzeumot. Napjainkban a múzeum földalatti galériái lenyűgöző betekintést nyújtanak Dubai múltjába, a régészeti leletektől kezdve az olajkorszak előtti mindennapi életig. A kiállításokon hagyományos hajók, fegyverek és helyi piaci jelenetek rekonstrukciói láthatók. Az Al Fahidi erőd fontos kulturális szimbólum, amely megőrzi a történelmi örökséget a modern metropolisz szívében.",
      ro: "Fortăreața Al Fahidi a fost construită în anul 1787 și este cea mai veche clădire existentă în Dubai. Inițial, a servit ca structură defensivă pentru a proteja orașul de invaziile de pe mare și uscat, fiind totodată sediul familiei domnitoare. Fortul are o formă pătrată, cu trei turnuri distinctive, iar zidurile sale sunt realizate din rocă de corali și scoici, îmbinate cu mortar de var. De-a lungul istoriei sale, a funcționat ca garnizoană, depozit de arme și închisoare, înainte de a fi transformat în Muzeul Dubai în 1971. Astăzi, muzeul oferă în galeriile sale subterane o perspectivă fascinantă asupra istoriei Dubaiului, de la descoperiri arheologice la viața cotidiană dinaintea descoperirii petrolului. Expozițiile includ ambarcațiuni tradiționale, arme și reconstrucții ale piețelor locale. Fortul Al Fahidi rămâne un simbol cultural central care păstrează moștenirea istorică în mijlocul metropolei moderne.",
      en: "Al Fahidi Fort was built in 1787 and is the oldest existing building in Dubai. It originally served as a defensive structure to protect the city from land and sea invasions and was also the seat of the ruling family. The square-shaped fort features three prominent towers and walls made of coral rock and shell limestone bonded with lime mortar. Throughout its history, the fort functioned as a garrison, an armory, and a prison before being converted into the Dubai Museum in 1971. Today, the museum's underground galleries offer fascinating insights into Dubai's history, from archaeological finds to daily life before the discovery of oil. Exhibits include traditional boats, weapons, and reconstructions of local marketplaces. Al Fahidi Fort remains a central cultural symbol, preserving historical heritage amidst the modern metropolis.",
      es: "El fuerte Al Fahidi, construido alrededor de 1799, es la estructura más antigua conservada de Dubái y hoy alberga el Museo de Dubái. El fuerte sirvió originalmente como residencia del gobernante, almacén de armas y prisión. Sus muros están hechos de piedra coralina y mortero, tradicionales en la región. En el patio interior hay torres de viento tradicionales (Barajeel) que protegen el edificio del calor. El museo muestra el desarrollo de Dubái, de pueblo pesquero a metrópolis, con artefactos anteriores a la extracción de petróleo. Las instalaciones fueron restauradas en 1971 y ampliadas en 1995. Cada año, más de un millón de turistas visitan el fuerte, considerado un símbolo de la ciudad.",
      pt: "O forte Al Fahidi, construído por volta de 1799, é a estrutura mais antiga preservada do Dubai e hoje alberga o Museu do Dubai. O forte serviu originalmente como residência do governante, armazém de armas e prisão. As suas muralhas são feitas de pedra coral e argamassa, tradicionais na região. No pátio interior encontram-se torres de vento tradicionais (Barajeel), que protegem o edifício do calor. O museu mostra o desenvolvimento do Dubai, de vila piscatória a metrópole, com artefactos anteriores à extração de petróleo. As instalações foram restauradas em 1971 e ampliadas em 1995. Todos os anos, mais de um milhão de turistas visitam o forte, que é considerado um símbolo da cidade.",
      fr: "Le fort Al Fahidi, construit vers 1799, est la plus ancienne structure conservée de Dubaï et abrite aujourd'hui le musée de Dubaï. Le fort servait à l'origine de résidence au souverain, de dépôt d'armes et de prison. Ses murs sont faits de pierre de corail et de mortier, traditionnels dans la région. Dans la cour intérieure se trouvent des tours à vent traditionnelles (Barajeel) qui protègent le bâtiment de la chaleur. Le musée retrace le développement de Dubaï, passant d'un village de pêcheurs à une métropole, avec des artefacts datant d'avant l'extraction pétrolière. Le site a été restauré en 1971 et agrandi en 1995. Chaque année, plus d'un million de touristes visitent le fort, considéré comme un symbole de la ville.",
    },
