      hu: ["A sírok az Umm an-Nar korszakhoz (i. e. 2500–2000) tartoznak.", "Az Al Ain-i történelmi Al Qattara oázis közelében találhatók.", "Az 1970-es években végzett feltárások jelentős mennyiségű aranyékszert tártak fel.", "A sírok kör alakúak, átmérőjük eléri a 8 métert.", "A helyszínen talált leleteket az Al Ain Nemzeti Múzeumban állítják ki.", "A lelőhely az Egyesült Arab Emírségek első UNESCO világörökségi listájának része."],
      ro: ["Mormintele aparțin perioadei Umm an-Nar (2500–2000 î.Hr.).", "Sunt situate lângă oaza istorică Al Qattara din Al Ain.", "Săpăturile din anii 1970 au scos la iveală cantități semnificative de bijuterii din aur.", "Mormintele au formă circulară și măsoară până la 8 metri în diametru.", "Artefactele găsite la sit sunt expuse în Muzeul Național Al Ain.", "Situl face parte din prima înscriere în Patrimoniul Mondial UNESCO din EAU."],
      en: ["The tombs belong to the Umm an-Nar period (2500–2000 BCE).", "They are located near the historic Al Qattara Oasis in Al Ain.", "Excavations in the 1970s revealed significant quantities of gold jewelry.", "The tombs are circular in shape and measure up to 8 meters in diameter.", "Artifacts found at the site are displayed in the Al Ain National Museum.", "The site is part of the first UNESCO World Heritage listing in the UAE."],
      es: ["Periodo: 2500-2000 a.C.", "Diámetro de las tumbas: hasta 8 m", "Descubrimiento: años 70", "Material: piedra caliza", "Objetos encontrados: esqueletos, cerámica, joyas", "Distancia a Al Ain: 15 km"],
      pt: ["Período: 2500-2000 a.C.", "Diâmetro dos túmulos: até 8 m", "Descoberta: anos 70", "Material: pedra calcária", "Objetos encontrados: esqueletos, cerâmica, joias", "Distância a Al Ain: 15 km"],
      fr: ["Période : 2500-2000 av. J.-C.", "Diamètre des tombes : jusqu'à 8 m", "Découverte : années 1970", "Matériau : calcaire", "Objets trouvés : squelettes, poteries, bijoux", "Distance d'Al Ain : 15 km"],
